16		type axis struct {
17			name      string
18			initX     float64
19			initY     float64
20			dx        []float64
21			dy        []float64
22			wantPoses [3][2]float64
23		}
24		cases := []axis{
25			{
26				name:      "x axis",
27				initX:     -1e308,
28				dx:        []float64{0, 1e308, 1e308},
29				dy:        []float64{0, 0, 0},
30				wantPoses: [3][2]float64{{-1e308, 0}, {0, 0}, {1e308, 0}},
31			},
32			{
33				name:      "y axis",
34				initY:     -1e308,
35				dx:        []float64{0, 0, 0},
36				dy:        []float64{0, 1e308, 1e308},
37				wantPoses: [3][2]float64{{0, -1e308}, {0, 0}, {0, 1e308}},
38			},
39			{
40				name:      "both axes",
41				initX:     -1e308,
42				initY:     -1e308,
43				dx:        []float64{0, 1e308, 1e308},
44				dy:        []float64{0, 1e308, 1e308},
45				wantPoses: [3][2]float64{{-1e308, -1e308}, {0, 0}, {1e308, 1e308}},
46			},
47		}
48		for _, ac := range cases {
49			t.Run(ac.name, func(t *testing.T) {
50				cfg := Config{
51					InitialTime: 0, InitialX: ac.initX, InitialY: ac.initY, InitialHeading: 0,
52					InitialVariance: 1, MaxInterval: 100, MergeDistance: 10,
53				}
54				m := newMap(t, cfg)
55				if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
56					{Time: 100, DX: ac.dx[0], DY: ac.dy[0], MoveVariance: 0.25},
57					{Time: 200, DX: ac.dx[1], DY: ac.dy[1], MoveVariance: 0.5},
58					{Time: 300, DX: ac.dx[2], DY: ac.dy[2], MoveVariance: 0.75},
59				}}); err != nil {
60					t.Fatal(err)
61				}
62	
63				anchor, _ := m.PoseAt(100)
64				rec, err := m.Correct(Correction{
65					ID:     "c",
66					Anchor: 100,
67					Target: CorrectionTarget{X: anchor.X, Y: anchor.Y, Heading: anchor.Heading, Variance: 4},
68				})
69				if err != nil {
70					t.Fatalf("variance-only correction on huge span rejected: %v", err)
71				}
72	
73				// 三个受影响帧：位置、朝向、时间不变，方差依次为 4、4.5、5.25。
74				wantVar := []float64{4, 4.5, 5.25}
75				wantTime := []int64{100, 200, 300}
76				if len(rec.Poses) != 3 {
77					t.Fatalf("record poses = %d, want 3 (anchor through last frame)", len(rec.Poses))
78				}
79				for i, p := range rec.Poses {
80					if p.Before.Time != wantTime[i] || p.After.Time != wantTime[i] {
81						t.Fatalf("pose %d time changed: %d -> %d", i, p.Before.Time, p.After.Time)
82					}
83					if p.Before.X != p.After.X || p.Before.Y != p.After.Y || p.Before.Heading != p.After.Heading {
